-- ============================================================================
-- FULL NSE EQUITY UNIVERSE — UPSTOX INSTRUMENT KEYS
--
-- Seeds public.instruments with every NSE_EQ / instrument_type=EQ row from
-- Upstox's own published instrument master
-- (https://assets.upstox.com/market-quote/instruments/exchange/NSE.json.gz,
-- downloaded and inspected 2026-09-16). This is the plain-equity segment —
-- it excludes SDL/SG bonds, ST/BE/SM/N-series and other non-equity
-- instrument_type codes present in the same NSE_EQ segment.
--
-- lot_size is 1 for every row (equities, not F&O). tick_size is Upstox's
-- published value divided by 100 to match this table's convention
-- (established by the index rows in 0010_instruments.sql, e.g. 0.05 rupees);
-- it is not consumed by any pricing/rounding logic today (grep confirms only
-- lot_size drives order-form behaviour), so treat it as descriptive metadata
-- pending confirmation, not a validated exchange tick.
-- ============================================================================

on conflict (exchange, symbol) do update set
  name = excluded.name,
  lot_size = excluded.lot_size,
  tick_size = excluded.tick_size,
  provider_token = excluded.provider_token;
